export function StudioRuntimeProvider({ children }: { children: ReactNode }) {
  const {
    messages,
    streaming,
    canvas,
    sendMessage,
    regenerateFrom,
    editFrom,
    switchBranch,
    respondToApproval,
    stopStreaming,
  } = useStudio();

  const attachments = useMemo(() => createAttachmentAdapter(), []);
  const jobCount = canvas?.jobs.length ?? 0;
  const outcomeCount = canvas?.outcomes.length ?? 0;
  const suggestions = useMemo(
    () => suggestionsFor({ jobCount, outcomeCount }),
    [jobCount, outcomeCount],
  );

  const runtime = useExternalStoreRuntime<ChatMessage>({
    isRunning: streaming,
    messages,
    convertMessage: toThreadMessageLike,
    suggestions,
    adapters: { attachments },
    onNew: async (message) => {
      await sendMessage(textOf(message), preparedAttachments(message.attachments));
    },
    onEdit: async (message) => {
      await editFrom(message.parentId, textOf(message), preparedAttachments(message.attachments));
    },
    onReload: async (parentId) => {
      await regenerateFrom(parentId);
    },
    onCancel: async () => {
      stopStreaming();
    },
    setMessages: (next) => {
      switchBranch([...next]);
    },
    onRespondToToolApproval: async ({ approvalId, approved, reason }) => {
      await respondToApproval(approvalId, approved, reason);
    },
  });

  return <AssistantRuntimeProvider runtime={runtime}>{children}</AssistantRuntimeProvider>;
}

/**
 * The one mapping between the Studio's message model and assistant-ui's.
 *
 * Kept in one place and pure, so the thread can be tested without a runtime and
 * the runtime can be swapped without touching the transcript. Anything the
 * conversion does not understand is dropped rather than rendered as raw JSON:
 * an unknown part must never reach the screen as machine text.
