          args: {},
          argsText: "{}",
          approval: { id: approval.id, prompt: approval.prompt },
        };
      }

export type ChatPart =
  | { kind: "text"; text: string }
  | { kind: "reasoning"; text: string }
  | { kind: "ui"; id: string; node: UiNode }
  | {
      kind: "tool";
      id: string;
      name: string;
      status: ToolStatus;
      preview?: string;
      /** Present while the runtime is waiting for the user's answer. */
      approval?: ToolApproval;
    }
  | {
      kind: "source";
      id: string;
      title: string;
      filename?: string;
      mediaType: string;
    };

export interface ChatMessage {
  /** Stable id. Branching and persisted turns are keyed by it. */
  id: string;
  /** The message this one answers; `null` at the root of a branch. */
  parentId: string | null;
  role: "user" | "assistant" | "notice";
  content: string;
  /**
   * Assistant turns only: prose and surfaces in the order the agent produced
   * them, so a card sits between the paragraphs that frame it. `content` stays
--
  parts?: ChatPart[];
  /** Files the user attached to this turn. */
  attachments?: ChatAttachment[];
  /**
   * Assistant turns only: the failure that ended this turn, so the transcript
   * can show it in place instead of losing the question.
   */
  error?: StudioError;
  /** The question this turn answered, kept so a failed turn can be retried. */
  retryText?: string;
}

/**
 * The user's context, captured on first run. Kept in local storage and sent to
 * the sidecar so every reply starts from the user's actual product and job.
 */
export interface StudioBrief {
  product_name: string;
  product_url?: string;
  target_user: string;
  job_statement: string;
  core_problem: string;
  job_id?: string;
}

/**
 * Lenses reachable from the rail and the bar. Chat is always the primary
 * stage; a lens makes room for itself and never replaces the thread.
 */
export type WorkspacePanelId =
  | "landscape"

export type ChatPart =
  | { kind: "text"; text: string }
  | { kind: "ui"; id: string; node: UiNode };

/**
 * A file that travelled with a turn: its bytes, base64-encoded, and the media
 * type the sidecar needs to decide between image content and inlined text.
 */
export interface ChatAttachmentPayload {
  name: string;
  media_type: string;
  data: string;
}

export interface ChatMessage {
  /** Stable identity, so the thread runtime can address a turn to reload it. */
--
  parts?: ChatPart[];
  /**
   * Assistant turns only: the failure that ended this turn, so the transcript
   * can show it in place instead of losing the question.
   */
  error?: StudioError;
  /** The question this turn answered, kept so a failed turn can be retried. */
  retryText?: string;
  /** Files this turn carried. Only the newest turn is sent with its bytes. */
  attachments?: ChatAttachmentPayload[];
  /** The files a failed or stopped turn should send again, if it had any. */
  retryAttachments?: ChatAttachmentPayload[];
  /**
   * Assistant turns only: the tools the turn used, in the order they ran. Kept
   * on the turn so a finished run can still be inspected later.
   */

/**
 * The transcript.
 *
 * assistant-ui owns the message list, the message parts, and the branch picker;
 * this file decides what each of those looks like in the Studio. Everything it
 * renders comes from one place — `assistant/convert.ts` — so a new part type is
 * added in exactly two files.
 */

