export function CommandPalette({
  id,
  open,
  matches,
  activeIndex,
  onHover,
  onChoose,
}: {
  /** Unique per composer: two composers can be mounted at once. */
  id: string;
  open: boolean;
  matches: StudioCommand[];
  activeIndex: number;
  onHover: (index: number) => void;
  onChoose: (command: StudioCommand) => void;
}) {
  if (!open) {
    return null;
  }

  return (
    <div className="palette" role="listbox" id={id} aria-label="Commands">
      {matches.length ? (
        matches.map((command, index) => (
          <button
            key={command.id}
            type="button"
            role="option"
            aria-selected={index === activeIndex}
            className={`palette__item${index === activeIndex ? " is-active" : ""}`}
            onMouseEnter={() => onHover(index)}
            onClick={() => onChoose(command)}
          >
            <code className="palette__name">{command.name}</code>
            <span className="palette__text">
              <span className="palette__label">{command.label}</span>
              <span className="palette__description">{command.description}</span>
            </span>
          </button>
        ))
      ) : (
        <p className="palette__empty">
          No command matches. Type <code>/help</code> for the full list.
        </p>
      )}
    </div>
  );
}

export function ConnectorChips() {
  const {
    connectorSuggestions,
    presets,
    dismissConnectorSuggestion,
    refreshConnectors,
  } = useStudio();

  if (connectorSuggestions.length === 0) {
    return null;
  }

  return (
    <div className="composer__suggestions" aria-label="Connector suggestions">
      {connectorSuggestions.map((id) => {
        const label = presets.find((preset) => preset.id === id)?.label ?? id;
        return (
          <button
            key={id}
            type="button"
            className="composer__suggestion"
            aria-label={`Added ${label}, dismiss`}
            onClick={() => {
              dismissConnectorSuggestion(id);
              void refreshConnectors();
            }}
          >
            <span>Added {label}</span>
            <span aria-hidden>✕</span>
          </button>
        );
      })}
    </div>
  );
}

export function ComposerHint({ trailing }: { trailing?: ReactNode } = {}) {
  const { settings, llmHealth, brief } = useStudio();
  const offline = llmHealth.healthy === false;

  return (
    <div className="composer__hint">
      <span>
        <kbd>Enter</kbd> to send · <kbd>/</kbd> for commands
        {brief ? ` · ${brief.product_name || "your job"}` : ""}
      </span>
      <span className="composer__hint-end">
        {offline ? <span className="composer__status is-offline">Local guidance</span> : null}
        {trailing ??
          (offline ? null : <span className="composer__status">{settings.model_name}</span>)}
      </span>
    </div>
  );
}

/** Whether a draft should open the command palette. */
export function paletteOpenFor(value: string): boolean {
  return isCommandDraft(value);
}

#: Columns added after the first release. A database created by an older build
#: is upgraded in place: nothing is dropped and no data is rewritten.
_MIGRATIONS: tuple[tuple[str, str, str], ...] = (
    ("conversations", "head_id", "TEXT"),
    ("turns", "message_id", "TEXT"),
    ("turns", "parent_id", "TEXT"),
)


def _migrate(connection: sqlite3.Connection) -> None:
    for table, column, kind in _MIGRATIONS:
        columns = {
            row["name"] for row in connection.execute(f"PRAGMA table_info({table})").fetchall()
        }
        if column not in columns:
            connection.execute(f"ALTER TABLE {table} ADD COLUMN {column} {kind}")
    connection.execute(
        "CREATE INDEX IF NOT EXISTS turns_by_message ON turns(conversation_id, message_id)"
    )


def _validate_text(text: str) -> str:
    cleaned = text.strip()
    if not cleaned:
        raise MemoryError("observation text cannot be empty")
    if len(cleaned) > MAX_TEXT:
        raise MemoryError(f"observation text cannot exceed {MAX_TEXT} characters")
    return cleaned


def _validate_kind(kind: str) -> str:
    if kind not in OBSERVATION_KINDS:
        raise MemoryError(f"unknown observation kind: {kind}")
    return kind


def _validate_status(status: str) -> str:
    if status not in OBSERVATION_STATUSES:
        raise MemoryError(f"unknown observation status: {status}")
    return status


def _validate_confidence(confidence: float) -> float:
    value = float(confidence)
    if not 0.0 <= value <= 1.0:
        raise MemoryError("confidence must be between 0 and 1")
    return value


def _validate_data(data: dict[str, Any] | None) -> dict[str, Any]:
    if data is None:
        return {}
    if not isinstance(data, dict):
        raise MemoryError("observation data must be an object")
    return data


class StudioMemory:
    """A small SQLite store for conversations, turns, and observations."""

    def __init__(self, path: str | Path | None = None) -> None:
        resolved = default_db_path() if path is None else path
        self._memory = str(resolved) == ":memory:"
        self.db_path = Path(":memory:") if self._memory else Path(resolved)
        if not self._memory:
            self.db_path.parent.mkdir(parents=True, exist_ok=True)

        self._lock = threading.RLock()
        self._connection = sqlite3.connect(
            ":memory:" if self._memory else str(self.db_path),
            check_same_thread=False,
        )
        self._connection.row_factory = sqlite3.Row
        self._connection.execute("PRAGMA foreign_keys = ON")
        if not self._memory:
            self._connection.execute("PRAGMA journal_mode = WAL")
            # Another process may be mid-write; wait for it briefly rather
            # than failing the turn with "database is locked".
            self._connection.execute("PRAGMA busy_timeout = 5000")
        with self._connection:
            self._connection.executescript(_SCHEMA)
            _migrate(self._connection)

    def close(self) -> None:
        with self._lock:
            self._connection.close()

    # -- conversations -----------------------------------------------------

    def create_conversation(self, title: str = "") -> Conversation:
        conversation = Conversation(
            id=uuid.uuid4().hex,
            title=title.strip(),
            created_at=_now(),
            updated_at=_now(),
        )
        with self._lock, self._connection:
            self._connection.execute(
                "INSERT INTO conversations (id, title, created_at, updated_at) VALUES (?, ?, ?, ?)",
                (
                    conversation.id,
                    conversation.title,
                    conversation.created_at,
                    conversation.updated_at,
                ),
            )
        return conversation

    def get_conversation(self, conversation_id: str) -> Conversation | None:
        with self._lock:
            row = self._connection.execute(
                "SELECT * FROM conversations WHERE id = ?", (conversation_id,)
            ).fetchone()
        return None if row is None else self._conversation_from_row(row)

    def latest_conversation(self) -> Conversation | None:
        with self._lock:
            row = self._connection.execute(
                "SELECT * FROM conversations ORDER BY updated_at DESC, created_at DESC LIMIT 1"
            ).fetchone()
        return None if row is None else self._conversation_from_row(row)

    def append_turn(
        self,
        conversation_id: str,
        role: str,
        content: str,
        message_id: str | None = None,
        parent_id: str | None = None,
    ) -> None:
        if role not in TURN_ROLES:
            raise MemoryError(f"unknown turn role: {role}")

        now = _now()
        with self._lock, self._connection:
            exists = self._connection.execute(
                "SELECT 1 FROM conversations WHERE id = ?", (conversation_id,)
            ).fetchone()
            if exists is None:
                raise ConversationNotFoundError(conversation_id)

            self._connection.execute(
                "INSERT INTO turns "
                "(conversation_id, role, content, created_at, message_id, parent_id) "
                "VALUES (?, ?, ?, ?, ?, ?)",
                (conversation_id, role, content, now, message_id, parent_id),
            )
            if message_id:
                self._connection.execute(
                    "UPDATE conversations SET head_id = ? WHERE id = ?",
                    (message_id, conversation_id),
                )

            title = ""
            if role == "user" and content.strip():
                title = content.strip()[:80]
            if title:
                self._connection.execute(
                    "UPDATE conversations SET title = ?, updated_at = ? "
                    "WHERE id = ? AND title = ''",
                    (title, now, conversation_id),
                )
            self._connection.execute(
                "UPDATE conversations SET updated_at = ? WHERE id = ?",
                (now, conversation_id),
            )

    def list_turns(self, conversation_id: str) -> list[Turn]:
        with self._lock:
            exists = self._connection.execute(
                "SELECT 1 FROM conversations WHERE id = ?", (conversation_id,)
            ).fetchone()
            if exists is None:
                raise ConversationNotFoundError(conversation_id)
            rows = self._connection.execute(
                "SELECT * FROM turns WHERE conversation_id = ? ORDER BY id ASC",
                (conversation_id,),
            ).fetchall()
        return [self._turn_from_row(row) for row in rows]

    def set_head(self, conversation_id: str, head_id: str | None) -> Conversation:
        """Record which branch is visible, so a reload opens the same one."""
        now = _now()
        with self._lock, self._connection:
            exists = self._connection.execute(
                "SELECT 1 FROM conversations WHERE id = ?", (conversation_id,)
            ).fetchone()
            if exists is None:
                raise ConversationNotFoundError(conversation_id)
            self._connection.execute(
                "UPDATE conversations SET head_id = ?, updated_at = ? WHERE id = ?",
                (head_id, now, conversation_id),
            )
        return self._updated_conversation(conversation_id)

    def update_title(self, conversation_id: str, title: str) -> Conversation:
        now = _now()
        with self._lock, self._connection:
            exists = self._connection.execute(
                "SELECT 1 FROM conversations WHERE id = ?", (conversation_id,)
            ).fetchone()
            if exists is None:
                raise ConversationNotFoundError(conversation_id)
            self._connection.execute(
                "UPDATE conversations SET title = ?, updated_at = ? WHERE id = ?",
                (title.strip()[:200], now, conversation_id),
            )
        return self._updated_conversation(conversation_id)

    def _updated_conversation(self, conversation_id: str) -> Conversation:
        """Read back a row this instance just wrote.

        A missing row here means the store was mutated underneath us after the
        existence check, which is a not-found, not an assertion.
        """
        conversation = self.get_conversation(conversation_id)
        if conversation is None:
            raise ConversationNotFoundError(conversation_id)
        return conversation

    def conversation_tree(self, conversation_id: str) -> list[Turn]:
        """Turns in insertion order, with a linear chain synthesized for old rows.

        Rows written before message ids existed have no ``message_id``; they are
        given a stable one derived from their row id and chained to the previous
        row, so an old conversation opens exactly as it did.
        """
        turns = self.list_turns(conversation_id)
        previous: str | None = None
        for turn in turns:
            if turn.message_id is None:
                turn.message_id = f"turn-{turn.id}"
                turn.parent_id = previous
            previous = turn.message_id
        return turns

    # -- observations ------------------------------------------------------

    def list_observations(self, include_dismissed: bool = False) -> list[Observation]:
        query = "SELECT * FROM observations"
        params: tuple[Any, ...] = ()
        if not include_dismissed:
            query += " WHERE status != ?"
            params = ("dismissed",)
        query += " ORDER BY created_at ASC, rowid ASC"
        with self._lock:
            rows = self._connection.execute(query, params).fetchall()
        return [self._observation_from_row(row) for row in rows]

import { describe, expect, it } from "vitest";

import type { ChatMessage } from "../types";
import { catalogManifest } from "../ui/catalog";
import { parseUiSpec, type UiNode } from "../ui/protocol";
import { SURFACE_PART, textOf, toThreadMessageLike } from "./convert";

function nodeOf(spec: unknown): UiNode {
  const parsed = parseUiSpec(spec, catalogManifest());
  if (!parsed.ok) {
    throw new Error(parsed.reason);
  }
  return parsed.node;
}

const card = nodeOf({
  type: "outcome-card",
  props: {
    id: "O-1",
    statement: "Minimize the time it takes to propagate secrets",
    importance: 9,
    satisfaction: 3,
  },
});

function assistant(overrides: Partial<ChatMessage> = {}): ChatMessage {
  return {
    id: "m-1",
    parentId: null,
    role: "assistant",
    content: "",
    ...overrides,
  };
}

describe("toThreadMessageLike", () => {
  it("maps prose to a text part", () => {
    const message = toThreadMessageLike(assistant({ content: "Hello." }));

    expect(message.role).toBe("assistant");
    expect(message.content).toEqual([{ type: "text", text: "Hello." }]);
  });

  it("keeps the agent's part order", () => {
    const message = toThreadMessageLike(
      assistant({
        content: "beforeafter",
        parts: [
          { kind: "text", text: "before" },
          { kind: "ui", id: "ui-1", node: card },
          { kind: "text", text: "after" },
        ],
      }),
    );

    expect((message.content as unknown as { type: string }[]).map((part) => part.type)).toEqual([
      "text",
      `data-${SURFACE_PART}`,
      "text",
    ]);
  });

  it("carries a generated surface as a named data part", () => {
    const message = toThreadMessageLike(
      assistant({
        parts: [{ kind: "ui", id: "ui-1", node: card }],
      }),
    );

    const part = (message.content as { type: string; id?: string; data?: UiNode }[])[0];
    expect(part.type).toBe(`data-${SURFACE_PART}`);
    expect(part.id).toBe("ui-1");
    expect(part.data).toEqual(card);
  });

  it("maps reasoning to a reasoning part", () => {
    const message = toThreadMessageLike(
      assistant({ parts: [{ kind: "reasoning", text: "weighing options" }] }),
    );

    expect(message.content).toEqual([{ type: "reasoning", text: "weighing options" }]);
  });

  it("maps a finished tool call to a result, not a question", () => {
    const message = toThreadMessageLike(
      assistant({
        parts: [
          { kind: "tool", id: "call-1", name: "get_jobs", status: "ok", preview: "3 jobs" },
        ],
      }),
    );

    const part = (
      message.content as {
        type: string;
        toolCallId?: string;
        toolName?: string;
        result?: { status?: string; preview?: string };
        isError?: boolean;
      }[]
    )[0];
    expect(part.type).toBe("tool-call");
    expect(part.toolCallId).toBe("call-1");
    expect(part.toolName).toBe("get_jobs");
    expect(part.result).toEqual({ status: "ok", preview: "3 jobs" });
    expect(part.isError).toBe(false);
  });

  it("marks a failed tool call as an error without inventing a result", () => {
    const message = toThreadMessageLike(
      assistant({
        parts: [{ kind: "tool", id: "call-1", name: "get_jobs", status: "error" }],
      }),
    );

    const part = (
      message.content as unknown as { isError?: boolean; result?: { status?: string } }[]
    )[0];
    expect(part.isError).toBe(true);
    expect(part.result?.status).toBe("error");
  });

  it("turns a pending approval into a question the runtime keeps open", () => {
    const message = toThreadMessageLike(
      assistant({
        parts: [
          {
            kind: "tool",
            id: "call-1",
            name: "add_job",
            status: "running",
            approval: { id: "apv_1", prompt: "Allow the assistant to add job?" },
          },
        ],
      }),
    );

    const part = (
      message.content as unknown as {
        approval?: { id?: string; prompt?: string };
        result?: unknown;
      }[]
    )[0];
    expect(part.approval).toEqual({ id: "apv_1", prompt: "Allow the assistant to add job?" });
    expect(part.result).toBeUndefined();
  });

  it("maps a source to a document citation", () => {
    const message = toThreadMessageLike(
      assistant({
        parts: [
          {
            kind: "source",
            id: "src-1",
            title: "get_jobs — JOB-1",
            filename: "get_jobs",
            mediaType: "application/json",
          },
        ],
      }),
    );

